WITH ranked AS (SELECT id, carrier, delivered_date, cost FROM (SELECT *, RANK() OVER (PARTITION BY status ORDER BY cost) AS row_num FROM shipments) t WHERE row_num = 1), filtered AS (SELECT *, CAST(cost AS INT) AS cost_int, LENGTH(carrier) AS carrier_length FROM ranked WHERE YEAR(delivered_date) >= 2024 AND carrier IS NOT NULL), enriched AS (SELECT id, delivered_date, cost_int, carrier_length, CUME_DIST() OVER (PARTITION BY YEAR(delivered_date), carrier ORDER BY carrier_length DESC NULLS LAST) AS carrier_length_cume_dist, AVG(carrier_length) OVER (ORDER BY carrier_length, id ROWS BETWEEN 2 PRECEDING AND CURRENT ROW) AS carrier_length_avg_2 FROM filtered), cleaned AS (SELECT *, FLOOR(carrier_length) AS carrier_length_whole, CAST(carrier_length AS STRING) AS carrier_length_str FROM enriched WHERE delivered_date > DATE '2023-06-01') SELECT id, cost_int, carrier_length, carrier_length_cume_dist, carrier_length_avg_2, carrier_length_str FROM cleaned;
